def section_68_applicable_amount(facts):
    status = facts.get('filing_status')
    amounts = {
        'joint_return': 300000,
        'surviving_spouse': 300000,
        'head_of_household': 275000,
        'unmarried': 250000,
        'married_filing_separately': 150000
    }
    if status in amounts:
        return {'value': amounts[status], 'used_units': ['u68_b1_qty'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u68_b1_qty'], 'open_dependencies': ['filing_status under sections 2 and 7703']}


def section_68_nonapplication(facts):
    year = facts.get('tax_year_begin_year')
    if isinstance(year, (int, float)) and not isinstance(year, bool):
        return {'value': year >= 2018 and year < 2026, 'used_units': ['u68_f_pred'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u68_f_pred'], 'open_dependencies': ['tax_year_begin_year']}


def section_68_itemized_deduction_limitation_applies(facts):
    nonapplication = section_68_nonapplication(facts)
    if nonapplication['value'] is True:
        return {'value': False, 'used_units': ['u68_a_pred', 'u68_b1_qty', 'u68_f_pred'], 'open_dependencies': []}
    individual = facts.get('taxpayer_is_individual')
    if individual is False:
        return {'value': False, 'used_units': ['u68_a_pred', 'u68_b1_qty', 'u68_f_pred'], 'open_dependencies': []}
    threshold = section_68_applicable_amount(facts)
    agi = facts.get('adjusted_gross_income')
    if threshold['value'] is not None and isinstance(agi, (int, float)) and not isinstance(agi, bool):
        if agi <= threshold['value']:
            return {'value': False, 'used_units': ['u68_a_pred', 'u68_b1_qty', 'u68_f_pred'], 'open_dependencies': []}
        if individual is True and nonapplication['value'] is False:
            return {'value': True, 'used_units': ['u68_a_pred', 'u68_b1_qty', 'u68_f_pred'], 'open_dependencies': []}
    deps = []
    if nonapplication['value'] is None:
        deps.extend(nonapplication['open_dependencies'])
    if individual is not True:
        deps.append('taxpayer_is_individual')
    if threshold['value'] is None:
        deps.extend(threshold['open_dependencies'])
    if not isinstance(agi, (int, float)) or isinstance(agi, bool):
        deps.append('adjusted_gross_income')
    return {'value': None, 'used_units': ['u68_a_pred', 'u68_b1_qty', 'u68_f_pred'], 'open_dependencies': sorted(set(deps))}


def section_68_itemized_deduction_reduction(facts):
    applies = section_68_itemized_deduction_limitation_applies(facts)
    units = ['u68_a_pred', 'u68_a_qty', 'u68_b1_qty', 'u68_f_pred']
    if applies['value'] is False:
        return {'value': 0, 'used_units': units, 'open_dependencies': []}
    if applies['value'] is None:
        return {'value': None, 'used_units': units, 'open_dependencies': applies['open_dependencies']}
    deductions = facts.get('itemized_deductions_otherwise_allowable')
    if not isinstance(deductions, (int, float)) or isinstance(deductions, bool):
        return {'value': None, 'used_units': units, 'open_dependencies': ['itemized_deductions_otherwise_allowable']}
    threshold = section_68_applicable_amount(facts)['value']
    agi = facts.get('adjusted_gross_income')
    return {'value': min(0.03 * (agi - threshold), 0.80 * deductions), 'used_units': units, 'open_dependencies': []}


