        joint_condition = True
        joint_deps = []
    elif joint is True and refund_only is True:
        joint_condition = True
        joint_deps = []
    elif joint is True and refund_only is False:
        joint_condition = False
        joint_deps = []
    elif joint is True:
        joint_condition = None
        joint_deps = ['joint_return_was_only_for_refund_claim']
    else:
        joint_condition = None
        joint_deps = ['individual_filed_joint_return_with_spouse']
    conditions = [relationship['value'], abode if isinstance(abode, bool) else None, age['value'], joint_condition]
    units = ['u152_c1_pred', 'u152_c2_pred', 'u152_c3_pred']
    if False in conditions:
        return {'value': False, 'used_units': units, 'open_dependencies': []}
    if all(value is True for value in conditions):
        return {'value': True, 'used_units': units, 'open_dependencies': []}
