def section_152_qualifying_relative(facts):
    relationship = section_152_qualifying_relative_relationship(facts)
    income = facts.get('individual_income_for_calendar_year')
    income_condition = income == 0 if isinstance(income, (int, float)) and not isinstance(income, bool) else None
    aggregate_qc = facts.get('individual_is_qualifying_child_of_any_taxpayer_for_relevant_year')
    qc_deps = []
    if isinstance(aggregate_qc, bool):
        not_qc = not aggregate_qc
    else:
        current_qc = section_152_qualifying_child(facts)
        other_qc = facts.get('individual_is_qualifying_child_of_any_other_taxpayer_for_relevant_year')
        if current_qc['value'] is True or other_qc is True:
            not_qc = False
        elif current_qc['value'] is False and other_qc is False:
            not_qc = True
        else:
            not_qc = None
            if current_qc['value'] is None:
                qc_deps.extend(current_qc['open_dependencies'])
            if not isinstance(other_qc, bool):
                qc_deps.append('individual_is_qualifying_child_of_any_other_taxpayer_for_relevant_year')
    conditions = [relationship['value'], income_condition, not_qc]
    units = ['u152_d1_pred', 'u152_d2_pred', 'u152_c1_pred', 'u152_c2_pred', 'u152_c3_pred']
    if False in conditions:
        return {'value': False, 'used_units': units, 'open_dependencies': []}
    if all(value is True for value in conditions):
        return {'value': True, 'used_units': units, 'open_dependencies': []}
    deps = []
    if relationship['value'] is None:
        deps.extend(relationship['open_dependencies'])
    if income_condition is None:
        deps.append('individual_income_for_calendar_year')
    if not_qc is None:
        if not isinstance(aggregate_qc, bool):
            deps.append('individual_is_qualifying_child_of_any_taxpayer_for_relevant_year, or facts resolving current-taxpayer and other-taxpayer qualifying-child status')
            deps.extend(qc_deps)
    return {'value': None, 'used_units': units, 'open_dependencies': sorted(set(deps))}


