    return {'value': None, 'used_units': ['u151_d3a_pred', 'u68_b1_qty'], 'open_dependencies': deps}


def section_151_applicable_percentage(facts):
    threshold = section_68_applicable_amount(facts)
    agi = facts.get('adjusted_gross_income')
    units = ['u151_d3b_qty', 'u68_b1_qty']
    deps = []
    if threshold['value'] is None:
        deps.extend(threshold['open_dependencies'])
    if not isinstance(agi, (int, float)) or isinstance(agi, bool):
        deps.append('adjusted_gross_income')
    if deps:
        return {'value': None, 'used_units': units, 'open_dependencies': deps}
    excess = agi - threshold['value']
    if excess <= 0:
        return {'value': 0, 'used_units': units, 'open_dependencies': []}
    increment = 1250 if facts.get('filing_status') == 'married_filing_separately' else 2500
    steps = int(excess / increment)
    if excess > steps * increment:
        steps += 1
    return {'value': min(100, 2 * steps), 'used_units': units, 'open_dependencies': []}


def section_151_exemption_amount_after_phaseout(facts):
    percentage = section_151_applicable_percentage(facts)
    units = ['u151_d1_qty', 'u151_d3a_qty', 'u151_d3b_qty', 'u68_b1_qty']
    if percentage['value'] is None:
        return {'value': None, 'used_units': units, 'open_dependencies': percentage['open_dependencies']}
    return {'value': 2000 * (1 - percentage['value'] / 100), 'used_units': units, 'open_dependencies': []}


