def section_151_taxpayer_and_spouse_exemption_deduction(facts):
    units = ['u151_a_pred', 'u151_b_pred', 'u151_b_qty', 'u151_d1_qty', 'u151_d2_pred', 'u151_d3a_qty', 'u151_d3b_qty', 'u151_d5_pred', 'u151_d5_qty', 'u68_b1_qty']
