        deps = individual['open_dependencies'] + special['open_dependencies'] + ordinary['open_dependencies']
        return {'value': None, 'used_units': units, 'open_dependencies': sorted(set(deps))}
    disallowed = section_151_certain_dependent_disallowance_applies(facts)
    spouse = section_151_spouse_additional_exemption_qualifies(facts)
    if ordinary['value'] == 0:
        return {'value': 0, 'used_units': units, 'open_dependencies': []}
